const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.parent_asin || !body.marketplace_id) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_REQUIRED_FIELDS',
    message: 'parent_asin and marketplace_id are both required.'
  }}];
}

const asin = String(body.parent_asin).trim().toUpperCase();

// Amazon ASINs are exactly 10 alphanumeric characters.
if (!/^[A-Z0-9]{10}$/.test(asin)) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'INVALID_ASIN_FORMAT',
    message: 'parent_asin must be a 10-character alphanumeric Amazon ASIN (e.g. B0CVFVHY93).',
    parent_asin: body.parent_asin
  }}];
}

return [{ json: {
  decision: 'VALID',
  parent_asin: asin,
  marketplace_id: body.marketplace_id
}}];

const upstream = $input.first().json;
const req = $('Validate Input').first().json;

// A real Catalog Items response always carries the asin back.
if (!upstream || upstream.error || !upstream.asin) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'PARENT_NOT_FOUND',
    parent_asin: req.parent_asin,
    marketplace_id: req.marketplace_id,
    message: 'Amazon Catalog Items API did not return this ASIN for this marketplace. Check the ASIN, the marketplace_id, and that the stored refresh token is still valid.',
    upstream_raw: upstream
  }}];
}

function forMarketplace(list) {
  if (!Array.isArray(list)) return {};
  return list.find(function(e) { return e.marketplaceId === req.marketplace_id; }) || list[0] || {};
}

const summary = forMarketplace(upstream.summaries);
const ptEntry = forMarketplace(upstream.productTypes);
const relEntry = forMarketplace(upstream.relationships);

const groups = Array.isArray(relEntry.relationships) ? relEntry.relationships : [];
const variationGroup = groups.find(function(g) { return g.type === 'VARIATION'; }) || null;

const childAsins = (variationGroup && Array.isArray(variationGroup.childAsins)) ? variationGroup.childAsins : [];
const parentAsins = (variationGroup && Array.isArray(variationGroup.parentAsins)) ? variationGroup.parentAsins : [];
const variationTheme = (variationGroup && variationGroup.variationTheme) ? variationGroup.variationTheme : null;

const baseInfo = {
  brand: summary.brand || null,
  item_name: summary.itemName || null,
  product_type: ptEntry.productType || null,
  category: (summary.browseClassification && summary.browseClassification.displayName) || null
};

// Case 1: this ASIN has children -> it IS a variation parent.
if (childAsins.length > 0) {
  return [{ json: {
    decision: 'PARENT_CONFIRMED',
    parent_asin: req.parent_asin,
    marketplace_id: req.marketplace_id,
    parent_preview: Object.assign({}, baseInfo, {
      variation_theme: variationTheme ? (variationTheme.theme || null) : null,
      theme_attributes: variationTheme ? (variationTheme.attributes || []) : [],
      child_count: childAsins.length,
      child_asins: childAsins
    }),
    raw_variation_group: variationGroup
  }}];
}

// Case 2: this ASIN itself belongs to a parent -> it is a CHILD, not a parent.
if (parentAsins.length > 0) {
  return [{ json: {
    decision: 'NOT_A_PARENT',
    reason: 'ASIN_IS_A_CHILD',
    parent_asin: req.parent_asin,
    marketplace_id: req.marketplace_id,
    is_child_of: parentAsins,
    message: 'This ASIN is itself a child in an existing variation family. Enter its parent ASIN instead.',
    item_info: baseInfo,
    raw_variation_group: variationGroup
  }}];
}

// Case 3: no VARIATION relationship at all -> standalone listing.
return [{ json: {
  decision: 'NOT_A_PARENT',
  reason: 'NO_VARIATION_FAMILY',
  parent_asin: req.parent_asin,
  marketplace_id: req.marketplace_id,
  message: 'This ASIN exists but has no variation relationships in the catalog - it is a standalone listing, not a parent.',
  item_info: baseInfo
}}];
